const query = $input.first().json.query || {};
const mode = query['hub.mode'];
const token = query['hub.verify_token'];
const challenge = query['hub.challenge'];
const expected = $env.INSTAGRAM_VERIFY_TOKEN;
const verified = mode === 'subscribe' && typeof expected === 'string' && expected.length > 0 && token === expected;
return [{ json: { verified, challenge: challenge || '' } }];

const body = $input.first().json.body || {};
const events = [];
for (const entry of body.entry || []) {
  const receivedAt = new Date((entry.time || Math.floor(Date.now() / 1000)) * 1000).toISOString();
  // Commentaires (webhook field "comments")
  for (const change of entry.changes || []) {
    if (change.field !== 'comments') continue;
    const v = change.value || {};
    events.push({
      json: {
        event_type: 'comment',
        comment_id: v.id,
        comment_text: v.text || '',
        media_id: v.media ? v.media.id : undefined,
        media_product_type: v.media ? v.media.media_product_type : undefined,
        from_id: v.from ? v.from.id : null,
        username: v.from ? v.from.username : null,
        parent_id: v.parent_id || null,
        received_at: receivedAt,
      },
    });
  }
  // Clics sur un bouton postback dans un DM (webhook field "messaging_postbacks")
  for (const m of entry.messaging || []) {
    if (!m.postback || !m.postback.payload) continue;
    events.push({
      json: {
        event_type: 'postback',
        sender_id: m.sender ? m.sender.id : null,
        postback_payload: m.postback.payload,
        postback_title: m.postback.title || '',
        received_at: receivedAt,
      },
    });
  }
}
return events;

function normalize(text) {
  return (text || '')
    .toString()
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^\p{L}\p{N}\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}
return { json: { ...$json, normalized_text: normalize($json.comment_text) } };

// EDIT HERE: add / reorder / remove rules. Priority = array order, first match wins.
//
// followGate: true  -> parcours "abonne-toi pour recevoir le lien" :
//   1. DM avec un bouton (gateButtonTitle)
//   2. au clic : si la personne est abonnée -> linkMessage + bouton vers buttonUrl
//               sinon -> followMessage + boutons "M'abonner" et "C'est fait"
//   3. au clic sur "C'est fait" : nouvelle vérification (notYetMessage si toujours pas abonné)
// followGate: false -> DM direct avec le bouton vers buttonUrl (ou texte simple si buttonUrl est vide).
//
// Limites Meta : textes <= 640 caracteres, titres de bouton courts (< 20 caracteres).
const profileUrl = 'https://www.instagram.com/yosri.devengine/';

const rules = [
  {
    name: 'abc',
    keywords: ['abc', 'a-b-c', 'a b c'],
    followGate: true,
    dmMessages: [
      'Hello {{username}} 👋 Comme promis, voici ton guide gratuit « Les ABC de l\'IA ». Appuie sur le bouton juste en dessous 👇',
    ],
    gateButtonTitle: 'Obtenir mon guide',
    followMessage: '🔒 Dernière petite étape : abonne-toi à mon compte. Dès que c\'est fait, appuie sur « C\'est fait » et je t\'envoie le guide automatiquement.',
    notYetMessage: 'Je ne vois pas encore ton abonnement 👀 Abonne-toi puis appuie à nouveau sur « C\'est fait ».',
    followButtonTitle: 'M\'abonner',
    doneButtonTitle: 'C\'est fait ✅',
    linkMessage: 'Merci de me suivre 🙏 Voici ton guide « Les ABC de l\'IA » : prompts, images, vidéos et les meilleurs outils.',
    buttonTitle: '📘 Lire le guide',
    buttonUrl: 'https://broken-bison-10f.notion.site/Les-ABC-de-l-IA-Guide-pour-bien-d-marrer-4003c5701ae1818ebb64edbaacde90cf',
  },
];
const defaultDmMessages = [
  'Bonjour {{username}} 👋 Merci pour ton commentaire.',
];
return { json: { ...$json, rules, defaultDmMessages, profileUrl } };

function normalizeKeyword(k) {
  return k.toString().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
}
const text = $json.normalized_text || '';
let matched = null;
for (const rule of $json.rules) {
  const hit = rule.keywords.some((k) => text.includes(normalizeKeyword(k)));
  if (hit) { matched = rule; break; }
}
return {
  json: {
    ...$json,
    matched_rule: matched ? matched.name : null,
    matched_dm_messages: matched ? matched.dmMessages : $json.defaultDmMessages,
    follow_gate: !!(matched && matched.followGate),
    gate_button_title: matched ? (matched.gateButtonTitle || 'Obtenir') : null,
    button_title: matched && matched.buttonUrl ? (matched.buttonTitle || 'Ouvrir') : null,
    button_url: matched && matched.buttonUrl ? matched.buttonUrl : null,
  },
};

const list = ($json.matched_dm_messages && $json.matched_dm_messages.length) ? $json.matched_dm_messages : $json.defaultDmMessages;
const raw = list[Math.floor(Math.random() * list.length)];
const username = $json.username;
let text = raw.split('{{username}}').join(username || '').replace(/\s{2,}/g, ' ').trim();
// Safety net: never send a literal undefined/null or an unresolved {{...}} placeholder.
if (/undefined|null/i.test(text) || /\{\{.*?\}\}/.test(text)) {
  text = text.replace(/undefined|null/gi, '').replace(/\{\{.*?\}\}/g, '').replace(/\s{2,}/g, ' ').trim();
}
if (text.length > 640) text = text.slice(0, 637) + '...';

function buttonMessage(t, buttons) {
  return { attachment: { type: 'template', payload: { template_type: 'button', text: t, buttons } } };
}
let message;
if ($json.follow_gate) {
  // 1er DM : bouton postback -> le clic arrive sur le webhook (messaging_postbacks)
  message = buttonMessage(text, [{ type: 'postback', title: $json.gate_button_title, payload: 'GET|' + $json.matched_rule }]);
} else if ($json.button_url) {
  message = buttonMessage(text, [{ type: 'web_url', url: $json.button_url, title: $json.button_title }]);
} else {
  message = { text };
}
return { json: { ...$json, selected_dm: text, dm_request: { recipient: { comment_id: $json.comment_id }, message } } };

// La sortie HTTP ne contient que la reponse Meta : on recupere le contexte via l'item apparie.
const base = $('Select Random DM').item.json;
const body = $json.body || {};
return { json: { ...base, dm_status: 'sent', dm_message_id: body.message_id || null } };

// La sortie d'erreur HTTP ne contient que l'erreur : on recupere le contexte via l'item apparie.
const base = $('Select Random DM').item.json;
const err = $json.error || {};
// The exact shape of the error object can vary by n8n version - verify during testing.
const statusCode = Number(
  err.httpCode || err.statusCode || err.status ||
  (err.cause && (err.cause.httpCode || err.cause.statusCode)) || 0
);
const headers = err.headers || (err.cause && err.cause.headers) || {};
const retryAfterHeader = headers['retry-after'] || headers['Retry-After'];
const attempt = $runIndex + 1;
const maxAttempts = 3;
const permanent = [400, 401, 403].includes(statusCode);
const transient = [429, 500, 502, 503, 504].includes(statusCode);
const canRetry = !permanent && transient && attempt < maxAttempts;
const waitSeconds = retryAfterHeader ? Number(retryAfterHeader) : Math.pow(2, attempt);
return {
  json: {
    ...base,
    dm_attempt: attempt,
    dm_status_code: statusCode || null,
    dm_error_message: (err.message || JSON.stringify(err)).toString().slice(0, 500),
    dm_can_retry: canRetry,
    dm_wait_seconds: waitSeconds,
  },
};

