// Payload format: ACTION|rule  (GET|abc = 1er clic, CHECK|abc = clic sur "C'est fait")
const [action, rule] = String($json.postback_payload || '').split('|');
const valid = ['GET', 'CHECK'].includes(action) && !!$json.sender_id && $json.sender_id !== $env.INSTAGRAM_USER_ID;
return { json: { ...$json, postback_action: action, postback_rule: rule || '', postback_valid: valid } };

const rule = ($json.rules || []).find((r) => r.name === $json.postback_rule);
if (!rule) return { json: { ...$json, rule_found: false } };
return {
  json: {
    ...$json,
    rule_found: true,
    rule_name: rule.name,
    follow_gate: !!rule.followGate,
    follow_message: rule.followMessage || 'Abonne-toi à mon compte puis appuie sur « C\'est fait ».',
    not_yet_message: rule.notYetMessage || rule.followMessage || 'Je ne vois pas encore ton abonnement.',
    follow_button_title: rule.followButtonTitle || 'M\'abonner',
    done_button_title: rule.doneButtonTitle || 'C\'est fait',
    link_message: rule.linkMessage || 'Voici ton lien :',
    button_title: rule.buttonTitle || 'Ouvrir',
    button_url: rule.buttonUrl || null,
    profile_url: $json.profileUrl,
  },
};

const base = $('Resolve Postback Rule').item.json;
const body = $json.body || {};
return { json: { ...base, follower_username: body.username || null, is_follower: body.is_user_follow_business === true } };

// La verification a echoue (consentement, droits, panne Meta...) :
// on n'enferme pas la personne dans une boucle, on envoie le lien.
const base = $('Resolve Postback Rule').item.json;
const err = $json.error || {};
return { json: { ...base, is_follower: true, follow_check_error: (err.message || JSON.stringify(err)).toString().slice(0, 300) } };

const j = $json;
function buttonMessage(t, buttons) {
  return { attachment: { type: 'template', payload: { template_type: 'button', text: String(t).slice(0, 640), buttons } } };
}
let message;
let outcome;
if (j.is_follower || !j.follow_gate) {
  outcome = 'link_sent';
  message = j.button_url
    ? buttonMessage(j.link_message, [{ type: 'web_url', url: j.button_url, title: j.button_title }])
    : { text: j.link_message };
} else {
  outcome = j.postback_action === 'CHECK' ? 'still_not_following' : 'asked_to_follow';
  message = buttonMessage(j.postback_action === 'CHECK' ? j.not_yet_message : j.follow_message, [
    { type: 'web_url', url: j.profile_url, title: j.follow_button_title },
    { type: 'postback', title: j.done_button_title, payload: 'CHECK|' + j.rule_name },
  ]);
}
return { json: { ...j, outcome, reply_request: { recipient: { id: j.sender_id }, message } } };
